steps.code:
# I have the Venmo access token.
# Now I will search Venmo users for each roommate and Nancy by their email to get their Venmo user ids.
venmo_access_token = venmo_login_response["access_token"]

def get_venmo_user_id(email):
    users = apis.venmo.search_users(access_token=venmo_access_token, query=email)
    if users:
        return users[0].get("user_id") or users[0].get("id") or users[0].get("username")
    return None

# Get Venmo user id for Nancy
nancy_venmo_user_id = get_venmo_user_id(nancy_contact["email"])

# Get Venmo user ids for roommates (excluding Nancy)
roommates_venmo_user_ids = []
for roommate in roommates:
    if roommate["email"] != nancy_contact["email"]:
        user_id = get_venmo_user_id(roommate["email"])
        if user_id:
            roommates_venmo_user_ids.append((roommate, user_id))

nancy_venmo_user_id, roommates_venmo_user_ids[:5]  # Show Nancy's Venmo user id and first 5 roommates' user ids for verification.

