steps.code:
# I have the songs in each playlist. Now I will identify the songs that are in the old_songs list and prepare to remove them from their playlists.
# I will also collect these songs to add them to the "Archived Songs" playlist later.
songs_to_archive = []
songs_to_remove_by_playlist = {}

old_songs_set = set(old_songs)

for playlist_id, songs in playlists_songs.items():
    for song in songs:
        song_full_title = f"{song['title']} by "  # We will check if any old song starts with this title + " by"
        # Check if any old song matches this song title and artist pattern
        for old_song in old_songs_set:
            if old_song.startswith(song_full_title):
                songs_to_remove_by_playlist.setdefault(playlist_id, []).append(song["id"])
                songs_to_archive.append(song["id"])
                break

print(songs_to_remove_by_playlist)
print(songs_to_archive)  # To verify the songs to remove and archive.

